<template><section v-if="store.detail" class="section container article"><div class="eyebrow">{{ store.detail.kategori_nama || 'Berita' }}</div><h1>{{ store.detail.judul }}</h1><div class="meta">Oleh {{ store.detail.penulis || 'Redaksi' }} · {{ formatDate(store.detail.created_at) }} · {{ store.detail.views }} views</div><img v-if="store.detail.thumbnail" class="article-image" :src="imageUrl(store.detail.thumbnail)" :alt="store.detail.judul"><div class="article-content"><p class="lead">{{ store.detail.ringkasan }}</p><p>{{ store.detail.isi }}</p></div></section><section v-else class="section container empty">Berita tidak ditemukan.</section></template>
<script setup lang="ts">
const route = useRoute(); const store = useBeritaStore(); const config = useRuntimeConfig(); await store.fetchBySlug(route.params.slug).catch(() => {}); const imageUrl = (path) => `${config.public.uploadsBase}${path}`; const formatDate = (date) => new Date(date).toLocaleDateString('id-ID', { dateStyle: 'long' })
</script><style scoped>.article{max-width:850px}.article h1{font-size:clamp(2.2rem,5vw,4rem);line-height:1;margin:12px 0}.article-image{width:100%;margin:28px 0;border-radius:9px;max-height:500px;object-fit:cover}.article-content{font-size:1.15rem;line-height:1.8}.lead{font-size:1.35rem;font-weight:600}.article-content p{white-space:pre-line}</style>
